'use strict';
(()=>{
 const M=window.NhT,app=document.getElementById('app'),dialog=document.getElementById('dialog');
 const key='nhtbank-spec-v3';
 const cash=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={qr:'M3 3h6v6H3Zm12 0h6v6h-6ZM3 15h6v6H3Zm12 0h2v2h-2Zm4 0h2v6h-4v-2h-2',goal:'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5m-5 0 8-8m-3 0h3v3',user:'M20 21v-2a7 7 0 0 0-14 0v2m11-14a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12h4',plane:'m3 12 18-9-9 18-2-8Z',gift:'M3 8h18v4H3Zm2 4v9h14v-9M12 8v13m0-13C3 8 6 0 10 4l2 4c9 0 6-8 2-4Z',home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',send:'M5 12h14m-6-6 6 6-6 6',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v5l3 2',wallet:'M3 7h17v13H3V5l14-2v4m-1 5h5v4h-5Z',arrow:'M7 17 17 7M7 7h10v10',down:'m7 7 10 10M7 17h10V7',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12m13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',copy:'M9 9h12v12H9ZM3 15V3h12',shield:'m12 3 8 3v5c0 5-8 10-8 10S4 16 4 11V6ZM8 12l3 3 5-6',search:'M21 21l-5-5m2-6a8 8 0 1 1-16 0 8 8 0 0 1 16 0',coffee:'M4 9h12v6a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5Zm12 1h2a3 3 0 0 1 0 6h-2M7 3v3m5-3v3',bill:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 8h8m-8 4h6',logout:'M9 3H3v18h6m5-14 5 5-5 5m-7-5h12'};
 const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.wallet}"/></svg>`;
 const MODE='Bản minh họa · Không giao dịch tiền thật';
 const brand=()=>`<span class="logo-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M7 25V8a2 2 0 0 1 3-1l12 16M10 9l12 16a2 2 0 0 0 3-1V7" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></svg></span><span>NhT<span class="logo-light">Bank</span></span>`;
 let state=M.initial(),route='welcome',draft=null,transferStep=1,storageWarning='',toastTimer,lastFocus,stream=null,scanTimer=null,cameraBusy=false,cameraRequest=0,qrTab='receive',qrDraft={amount:'',note:''},lastQR=null,qrURL=null;
 let filters={query:'',direction:'all',status:'',from:'',to:''},scrollPositions={},pendingRoute=null,exportTask=null,navObserver=null;
 try{const raw=localStorage.getItem(key)||localStorage.getItem('nhtbank-studio-v2');if(raw){const saved=JSON.parse(raw);if(!M.valid(saved))throw Error();state=M.upgrade(saved);}}catch{storageWarning='Không đọc được dữ liệu đã lưu. Đang dùng phiên minh họa mới; dữ liệu cũ chưa bị ghi đè.';}
 const money=n=>state.settings.hideAll?'••••••':cash(n);
 const maskedNumber='•••• ••'+M.owner.number.slice(-4);
 const fullDate=date=>new Date(date).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false})+' (UTC+7)';
 const name=()=>state.profile.name,shortName=()=>name().trim().split(/\s+/).at(-1);
 const amountInputType=()=>state.settings.hideAll?'password':'text';
 const inputError=id=>`<p class="field-error" id="${id}-error"></p>`;
 function syncBadge(){const b=app.querySelector('[data-action="notifications"]');if(b){const unread=state.notifications.filter(n=>!n.read).length;b.setAttribute('aria-label',`Thông báo, ${unread} chưa đọc`);b.innerHTML=icon('bell')+(unread?'<span class="unread-dot"></span>':'');}}
 function save(){syncBadge();try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{storageWarning='Trình duyệt không cho lưu. Thay đổi chỉ tồn tại trong phiên này.';toast(storageWarning);return false;}}
 function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
 function closeDialog(force=false){const form=dialog.querySelector('form[data-baseline]');if(!force&&form&&form.dataset.baseline!==JSON.stringify([...new FormData(form)])&&!window.confirm('Bỏ dữ liệu đang nhập trong hộp thoại?'))return;dialog.close();}
 function showDialog(title,content){if(!dialog.open)lastFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-top"><span class="eyebrow">${MODE}</span><button data-action="close" aria-label="Đóng hộp thoại">${icon('close')}</button></div><h2 id="dialog-title" tabindex="-1">${title}</h2>${content}`;dialog.querySelectorAll('form').forEach(f=>f.dataset.baseline=JSON.stringify([...new FormData(f)]));if(!dialog.open)dialog.showModal();dialog.classList.toggle('transfer-dialog',title==='Kiểm tra và xác nhận');dialog.querySelector('#dialog-title').focus({preventScroll:true});dialog.scrollTop=0;}
 dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
 dialog.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();else document.querySelector('main h1')?.focus();});
 function dirty(){return [...app.querySelectorAll('form[data-baseline]')].some(f=>f.dataset.baseline!==JSON.stringify([...new FormData(f)]));}
 function stopCamera(){cameraRequest++;stream?.getTracks().forEach(t=>t.stop());stream=null;clearTimeout(scanTimer);scanTimer=null;cameraBusy=false;}
 function performNavigate(next){scrollPositions[route]=window.scrollY;stopCamera();route=next;render();requestAnimationFrame(()=>window.scrollTo(0,scrollPositions[next]||0));}
 function navigate(next){if(next===route)return;if(dirty()){pendingRoute=next;showDialog('Rời biểu mẫu đang nhập?',`<p>Dữ liệu chưa lưu trên biểu mẫu này sẽ được bỏ. Bạn có muốn tiếp tục?</p><div class="dialog-actions"><button class="secondary" data-action="close">Ở lại</button><button class="primary" data-action="leave-form">Rời biểu mẫu</button></div>`);return;}performNavigate(next);}
 const nav=[['home','home','Tổng quan'],['history','history','Giao dịch'],['qr','qr','QR'],['goals','goal','Mục tiêu'],['personal','user','Cá nhân']];
 function shell(content){
  const unread=state.notifications.filter(n=>!n.read).length;
  app.innerHTML=`<aside class="sidebar"><div class="brand">${brand()}</div><div class="sidebar-caption">TÀI CHÍNH TRONG TẦM TAY</div><nav aria-label="Điều hướng chính">${nav.map(([id,ico,label])=>`<button data-route="${id}" ${route===id?'aria-current="page"':''} class="nav-item ${route===id?'selected':''}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note">${icon('shield')}<p>Bản minh họa<small>Không giao dịch tiền thật</small></p></div><button class="help-button" data-action="help">Trợ giúp ${icon('arrow')}</button><div class="profile"><div class="avatar">${esc(shortName()[0])}</div><div><strong>${esc(shortName())}</strong><small>Dữ liệu trên thiết bị này</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand brand">${brand()}</div><div class="breadcrumb">NhTBank <span>/</span><strong>${nav.find(n=>n[0]===route)?.[2]||'Chuyển tiền'}</strong></div><div class="topbar-right"><button class="icon-button" data-action="notifications" aria-label="Thông báo, ${unread} chưa đọc">${icon('bell')}${unread?'<span class="unread-dot"></span>':''}</button><button class="avatar avatar-button" data-route="personal" aria-label="Mở Cá nhân">${esc(shortName()[0])}</button></div></header><main><div class="mode-banner">${icon('shield')}<span>${MODE}</span></div>${!navigator.onLine?`<p class="offline-banner" role="status">Bạn đang ngoại tuyến · Dữ liệu minh họa trên thiết bị. Cập nhật cuối: ${fullDate(state.accountUpdatedAt)}.</p>`:''}${storageWarning?`<p class="storage-warning" role="alert">${esc(storageWarning)}</p>`:''}${content}<footer>NhTBank · Tài chính trong tầm tay.<br>Nguồn: dữ liệu minh họa lưu cục bộ. Không có dịch vụ tiền thật đã kết nối.</footer></main></div><nav class="mobile-nav" aria-label="Điều hướng điện thoại">${nav.map(([id,ico,label])=>`<button data-route="${id}" class="${route===id?'selected':''}" ${route===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`).join('')}</nav>`;
  app.querySelectorAll('form').forEach(f=>f.dataset.baseline=JSON.stringify([...new FormData(f)]));
  navObserver?.disconnect();const mobileNav=app.querySelector('.mobile-nav');navObserver=new ResizeObserver(()=>document.documentElement.style.setProperty('--nav-height',mobileNav.getBoundingClientRect().height+'px'));navObserver.observe(mobileNav);
 }
 function welcome(){app.innerHTML=`<main class="welcome-screen"><div class="welcome-brand brand">${brand()}</div><div class="welcome-illustration" aria-hidden="true">${brand()}</div><div class="eyebrow">CHÀO MỪNG ĐẾN VỚI NHTBANK</div><h1>Tài chính<br>trong tầm tay.</h1><p>Quản lý tài khoản, theo dõi giao dịch và chủ động hơn với tiền của bạn.</p><button class="primary" data-route="home">Trải nghiệm bản minh họa ${icon('send')}</button><div class="mode-banner">${icon('shield')}<span>${MODE}</span></div><p class="small-note">Chưa có dịch vụ xác thực hoặc ngân hàng thật được kết nối. Không yêu cầu OTP, mật khẩu ngân hàng hay dữ liệu thẻ.</p><button class="text-link" data-action="privacy">Cách dữ liệu của bạn được lưu</button></main>`;}
 function transactionRows(list){return list.length?list.map((t,index)=>`<button class="transaction recent-${index}" data-transaction="${esc(t.id)}"><span class="tx-symbol ${t.amount>0?'positive':t.category}">${icon(t.amount>0?'down':t.category==='food'?'coffee':t.category==='bills'?'bill':'arrow')}</span><span class="tx-info"><strong>${esc(t.name)}</strong><small>${esc(t.note)}</small><span class="tx-status">${icon('check')} Hoàn tất · Mô phỏng</span></span><span class="tx-value"><strong class="${t.amount>0?'positive-text':''}">${state.settings.hideAll?'••••••':(t.amount>0?'+':'−')+cash(Math.abs(t.amount))}</strong><small>${new Date(t.date).toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})}</small></span></button>`).join(''):`<div class="empty-state">${icon('history')}<h3>Không tìm thấy giao dịch phù hợp.</h3><p>Thử đổi từ khóa hoặc mở rộng khoảng thời gian.</p></div>`;}
 function goalCard(g,featured=false){const percent=Math.min(100,Math.floor(g.progress/g.target*100)),remaining=Math.max(0,g.target-g.progress),late=g.deadline&&g.deadline<M.localDate(new Date());return `<article class="goal-card goal-${g.color}"><div class="section-title"><span class="quick-icon">${icon(g.icon)}</span><span class="status-pill">${g.progress>=g.target?'✓ Hoàn thành':late?'! Quá hạn kế hoạch':'Đang theo dõi'}</span></div><h3>${esc(g.name)}</h3><p><strong>${money(g.progress)}</strong> / ${money(g.target)}</p><div class="goal-track" ${state.settings.hideAll?'aria-label="Tiến độ đang ẩn"':`role="progressbar" aria-label="${esc(g.name)}" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"`}><span style="width:${state.settings.hideAll?0:percent}%"></span></div><p class="goal-caption">${state.settings.hideAll?'Tiến độ đang ẩn':percent+'%'} · Còn ${money(remaining)}</p>${g.deadline?`<p class="small-note">Dự kiến: ${esc(g.deadline)}${late?' · Có thể điều chỉnh kế hoạch':''}</p>`:''}<div class="goal-buttons"><button class="primary" data-progress="${esc(g.id)}">Ghi nhận tiến độ</button>${featured?'':`<button class="secondary" data-goal="${esc(g.id)}">Chi tiết</button>`}</div></article>`;}
 function home(){const st=M.monthStats(state);shell(`<section class="welcome"><div><h1 tabindex="-1">Xin chào, ${esc(shortName())}</h1></div></section><section class="balance-card"><div class="card-top"><span>Tài khoản chính · Mô phỏng</span><button data-action="balance" aria-label="${state.settings.hideBalance||state.settings.hideAll?'Hiện':'Ẩn'} số dư" ${state.settings.hideAll?'disabled title="Đang bật Ẩn số tiền toàn ứng dụng"':''}>${icon('eye')}</button></div><div class="balance-label">Số dư khả dụng</div><h2 id="balance">${state.settings.hideBalance||state.settings.hideAll?'••••••':cash(state.balance)}</h2><div class="card-bottom"><div><small>${esc(name())}</small><span>${maskedNumber}<button data-action="copy" aria-label="Sao chép số tài khoản">${icon('copy')}</button></span></div><button class="card-info" data-action="account-info">Chi tiết ${icon('arrow')}</button></div><p class="card-updated">Dữ liệu mẫu · Cập nhật ${new Date(state.accountUpdatedAt).toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'})}</p>${state.settings.hideAll?'<p class="card-privacy small-note">Ẩn số tiền toàn ứng dụng đang bật. Điều chỉnh tại Cá nhân.</p>':''}<div class="card-rings" aria-hidden="true"></div></section><section class="quick-actions four-actions">${[['transfer','send','Chuyển tiền'],['qr','down','Nhận tiền'],['history','history','Giao dịch'],['goals','goal','Mục tiêu']].map(([r,i,l])=>`<button data-route="${r}"><span class="quick-icon">${icon(i)}</span><strong>${l}</strong></button>`).join('')}</section><div class="spec-grid"><section class="money-overview"><div class="section-title"><div><h2>Dòng tiền tháng này</h2><p>Tài khoản ${maskedNumber} · Kỳ ${st.month}</p></div></div><div class="stats-three">${[['Tiền vào',st.income],['Tiền ra',st.outgoing],['Chênh lệch',st.net]].map(([l,n])=>`<div><small>${l}</small><strong>${money(n)}</strong></div>`).join('')}</div><p class="small-note">Chỉ tính giao dịch mô phỏng hoàn tất trong kỳ. Tiến độ mục tiêu không được tính vào dòng tiền.</p><div class="category-summary"><span>Chi tiêu đã phân loại</span><strong>${money(st.spending)}</strong></div><p class="small-note">Loại trừ danh mục chuyển tiền và chuyển giữa tài khoản của tôi.</p><button class="text-link" data-action="analysis">Xem phân tích theo danh mục ${icon('arrow')}</button></section><section class="panel activity"><div class="section-title"><h2>Giao dịch gần đây</h2><button class="text-link" data-route="history">Xem tất cả</button></div><div class="recent-list">${transactionRows(state.transactions.slice(0,5))}</div></section></div><section class="featured-goal"><div class="section-title"><h2>Mục tiêu nổi bật</h2><button class="text-link" data-route="goals">Xem tất cả</button></div>${state.goals[0]?goalCard(state.goals[0],true):'<p>Chưa có mục tiêu. Tạo kế hoạch đầu tiên tại Mục tiêu.</p>'}<p class="small-note">Tiến độ do bạn ghi nhận; số dư tài khoản không thay đổi.</p></section>`);}
 function stepper(step){return `<ol class="stepper" aria-label="Tiến trình chuyển tiền">${['Nhập thông tin','Kiểm tra','Kết quả'].map((t,i)=>`<li class="${i+1<=step?'current':''}" ${i+1===step?'aria-current="step"':''}><span>${i+1}</span>${t}</li>`).join('')}</ol>`;}
 function transfer(){const d=draft||{};shell(`<div class="page-heading"><button class="text-link" data-route="home">← Về Tổng quan</button><h1 tabindex="-1">Chuyển tiền mô phỏng</h1>${stepper(1)}</div><div class="transfer-layout"><section class="panel"><h2>Nhập thông tin</h2><form id="transfer-form" novalidate><label for="source">Tài khoản nguồn</label><select id="source" name="source"><option value="main">${maskedNumber} · Tài khoản mô phỏng</option></select><label for="recipient">Người nhận mẫu đã lưu</label><select id="recipient"><option value="">Tự nhập người nhận</option><option value="anh">Nguyễn Minh Anh (dữ liệu mẫu)</option></select><label for="bank">Ngân hàng nhận mẫu</label><select id="bank" name="bank" aria-describedby="bank-error">${M.banks.map(b=>`<option ${d.bank===b?'selected':''}>${esc(b)}</option>`).join('')}</select>${inputError('bank')}<label for="account">Số tài khoản nhận</label><input id="account" name="account" inputmode="numeric" maxlength="19" value="${esc(d.account||'')}" aria-describedby="account-error" required>${inputError('account')}<div class="unverified">! Chưa xác minh người nhận<br><small>Tên dưới đây do bạn tự nhập trong bản minh họa, không phải kết quả tra cứu ngân hàng.</small></div><label for="name">Tên ghi nhớ người nhận (mô phỏng)</label><input id="name" name="name" maxlength="60" value="${esc(d.name||'')}" aria-describedby="name-error" required>${inputError('name')}<label for="amount">Số tiền (VND)</label><input id="amount" name="amount" type="${amountInputType()}" inputmode="numeric" value="${d.amount?String(d.amount):''}" aria-describedby="amount-error available" required><p id="available" class="small-note">Số dư khả dụng: ${money(state.balance)}</p>${inputError('amount')}<div class="amount-chips">${[50000,100000,500000].map(n=>`<button type="button" data-amount="${n}" ${state.settings.hideAll?'disabled aria-describedby="quick-privacy"':''}>${money(n)}</button>`).join('')}</div>${state.settings.hideAll?'<p id="quick-privacy" class="small-note">Mức tiền gợi ý tạm ẩn. Bạn vẫn có thể nhập số tiền trực tiếp.</p>':''}<label for="note">Nội dung chuyển khoản</label><input id="note" name="note" maxlength="100" value="${esc(d.note||'')}" aria-describedby="note-error">${inputError('note')}<p class="error" id="form-error" role="alert"></p><button class="primary">Kiểm tra thông tin ${icon('send')}</button></form></section><aside class="transfer-aside"><div class="tips">${icon('shield')}<h2>Chỉ dùng dữ liệu mẫu</h2><p>Người nhận chưa được xác minh. Không gửi yêu cầu tới ngân hàng và không sử dụng OTP.</p><p>Phí mô phỏng đã xác định: ${money(0)}.</p></div></aside></div>`);}
 function transferErrors(form){const v=Object.fromEntries(new FormData(form));const errors={};if(!/^\d{6,19}$/.test(v.account))errors.account=v.account?'Số tài khoản cần có từ 6 đến 19 chữ số.':'Vui lòng nhập số tài khoản.';if(v.account===M.owner.number&&v.bank===M.owner.bank)errors.account='Hãy chọn tài khoản khác với tài khoản nguồn.';if(!v.name.trim())errors.name='Vui lòng nhập tên ghi nhớ người nhận.';try{v.amount=M.parseMoney(v.amount);if(v.amount<=0)errors.amount='Số tiền phải lớn hơn 0 ₫.';else if(v.amount>state.balance)errors.amount='Tổng tiền chuyển và phí vượt số dư khả dụng.';}catch(e){errors.amount=e.message;}for(const [field,msg]of Object.entries(errors)){const el=form.elements[field];el.setAttribute('aria-invalid','true');document.getElementById(field+'-error').textContent=msg;}if(Object.keys(errors).length){form.elements[Object.keys(errors)[0]].focus();throw Error('Vui lòng kiểm tra các trường được đánh dấu.');}return v;}
 function review(){transferStep=2;showDialog('Kiểm tra và xác nhận',`${stepper(2)}<p class="unverified">Chưa xác minh người nhận · Tên ghi nhớ do bạn nhập</p><h3 class="recipient-name">${esc(draft.name)}</h3><div class="review-amount">${money(draft.amount)}</div><p class="small-note">${state.settings.hideAll?'Số tiền bằng chữ đang được ẩn.':M.moneyWords(draft.amount)}</p><dl>${[['Ngân hàng nhận',draft.bank],['Số tài khoản nhận',draft.account],['Nội dung',draft.note],['Nguồn',M.owner.number+' · Tài khoản mô phỏng'],['Phí mô phỏng',money(0)],['Tổng tiền dự kiến trừ',money(draft.amount)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p id="confirm-error" class="error" role="alert"></p><div class="dialog-actions"><button class="secondary" data-action="edit">Chỉnh sửa</button><button class="primary" data-action="confirm">Xác nhận chuyển tiền mô phỏng</button></div>`);}
 function receipt(t,success=false){transferStep=3;const rows=[['Trạng thái','✓ Hoàn tất · Mô phỏng'],['Mã giao dịch',t.id],['Thời gian',fullDate(t.date)],['Tài khoản nguồn',t.amount<0?M.owner.number+' · Tài khoản mô phỏng':t.account+' · '+t.bank],['Người nhận',t.amount<0?t.name:name()],['Tài khoản nhận',t.amount<0?t.account:M.owner.number],['Ngân hàng mẫu',t.bank],['Số tiền',money(Math.abs(t.amount))],['Phí mô phỏng',money(t.fee||0)],['Tổng tiền trừ',t.amount<0?money(-t.amount+(t.fee||0)):'Không áp dụng cho tiền vào'],['Nội dung',t.note]];
 showDialog(success?'Chuyển tiền mô phỏng hoàn tất':'Chi tiết giao dịch mô phỏng',`<div class="receipt-status" aria-hidden="true">${icon('check')}</div><div class="receipt-watermark">MÔ PHỎNG — Không phải chứng từ thanh toán</div><div class="review-amount">${money(Math.abs(t.amount))}</div><p class="recipient-name">${esc(t.amount<0?t.name:name())}</p><dl>${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><details class="secondary-details"><summary>Chỉnh sửa danh mục</summary><label for="category">Danh mục</label><select id="category" data-category-transaction="${esc(t.id)}">${Object.entries(M.categories).map(([v,l])=>`<option value="${v}" ${t.category===v?'selected':''}>${l}</option>`).join('')}</select><p class="small-note">Đổi danh mục chỉ điều chỉnh phân tích chi tiêu, không đổi số dư.</p></details><button class="primary" data-export-receipt="${esc(t.id)}">Tải biên nhận (.txt)</button>`);}
 function filtered(){return M.selectTransactions(state,filters);}
 function history(){shell(`<div class="page-heading"><h1 tabindex="-1">Giao dịch</h1><p>Lịch sử giao dịch mô phỏng.</p></div><section class="panel history-panel"><form id="history-search"><label for="search">Tìm giao dịch</label><input id="search" name="query" type="search" placeholder="Tên, nội dung hoặc mã giao dịch" value="${esc(filters.query)}"><button class="visually-hidden" type="submit">Tìm kiếm</button></form><div class="filter-tabs direction-tabs">${[['all','Tất cả'],['in','Tiền vào'],['out','Tiền ra']].map(([v,l])=>`<button data-direction="${v}" aria-pressed="${filters.direction===v}" class="${filters.direction===v?'active':''}">${l}</button>`).join('')}</div><div class="history-tools"><button class="secondary" data-action="filters">Bộ lọc (${[filters.from,filters.to,filters.status].filter(Boolean).length})</button><details class="history-menu"><summary>Thao tác</summary><button class="text-link" data-action="clear-filters">Xóa bộ lọc</button><button class="text-link" data-action="export-history">Xuất lịch sử (.csv)</button></details></div><div id="filter-summary" class="filter-summary"></div><div id="history-rows"></div></section>`);updateHistory();}
 function filterDialog(){showDialog('Bộ lọc giao dịch',`<form id="history-filter" novalidate><label for="from">Từ ngày (UTC+7)</label><input id="from" name="from" type="date" value="${esc(filters.from)}"><label for="to">Đến ngày (UTC+7)</label><input id="to" name="to" type="date" value="${esc(filters.to)}"><label for="status-filter">Trạng thái</label><select id="status-filter" name="status"><option value="">Tất cả</option><option value="completed" ${filters.status?'selected':''}>Hoàn tất · Mô phỏng</option></select><p class="error" role="alert"></p><button class="primary">Áp dụng bộ lọc</button></form>`);}
 function updateHistory(){const list=filtered();const groups=new Map();for(const t of list){const day=M.localDate(new Date(t.date));if(!groups.has(day))groups.set(day,[]);groups.get(day).push(t);}const today=M.localDate(new Date()),yesterday=M.localDate(new Date(Date.now()-86400000));document.getElementById('history-rows').innerHTML=list.length?[...groups].map(([day,items])=>`<h2 class="day-heading">${day===today?'Hôm nay':day===yesterday?'Hôm qua':new Date(day+'T12:00:00+07:00').toLocaleDateString('vi-VN')}</h2>${transactionRows(items)}`).join(''):transactionRows([]);const labels=[['query',filters.query&&'Từ khóa: '+filters.query],['direction',filters.direction!=='all'&&(filters.direction==='in'?'Tiền vào':'Tiền ra')],['from',filters.from&&'Từ: '+filters.from],['to',filters.to&&'Đến: '+filters.to],['status',filters.status&&'Hoàn tất · Mô phỏng']];document.getElementById('filter-summary').innerHTML=`<p role="status">${list.length} kết quả · Tài khoản ${maskedNumber}</p>${labels.filter(x=>x[1]).map(([k,v])=>`<button data-clear-filter="${k}" aria-label="Xóa điều kiện ${esc(v)}">${esc(v)} ×</button>`).join('')}`;}
 function goals(){shell(`<div class="page-heading"><h1 tabindex="-1">Mục tiêu của tôi</h1><p>Tiến độ do bạn ghi nhận; số dư tài khoản không thay đổi.</p><button class="primary fit" data-action="new-goal">${icon('plus')} Tạo mục tiêu</button></div><div class="goal-grid">${state.goals.length?state.goals.map(g=>goalCard(g)).join(''):'<div class="empty-state"><h2>Kế hoạch mới bắt đầu từ đây</h2><p>Tạo một mục tiêu để theo dõi tiến độ của bạn.</p></div>'}</div>`);}
 function goalForm(g){showDialog(g?'Chỉnh sửa mục tiêu':'Tạo mục tiêu',`<form id="goal-form" data-id="${g?esc(g.id):''}" novalidate><label for="goal-name">Tên mục tiêu</label><input id="goal-name" name="name" maxlength="60" required value="${g?esc(g.name):''}"><label for="goal-target">Số tiền mong muốn (VND)</label><input id="goal-target" name="target" type="${amountInputType()}" inputmode="numeric" required value="${g?String(g.target):''}"><label for="goal-date">Ngày dự kiến (tùy chọn)</label><input id="goal-date" name="deadline" type="date" value="${g?esc(g.deadline):''}"><label for="goal-icon">Biểu tượng</label><select id="goal-icon" name="icon">${[['shield','Quỹ dự phòng'],['wallet','Máy tính / Mua sắm'],['plane','Chuyến đi'],['gift','Quà tặng']].map(([v,l])=>`<option value="${v}" ${g?.icon===v?'selected':''}>${l}</option>`).join('')}</select><label for="goal-color">Màu</label><select id="goal-color" name="color">${[['green','Xanh ngọc'],['blue','Xanh dương'],['gold','Vàng đậm']].map(([v,l])=>`<option value="${v}" ${g?.color===v?'selected':''}>${l}</option>`).join('')}</select><p class="error" role="alert"></p><button class="primary">${g?'Lưu mục tiêu':'Tạo mục tiêu'}</button></form>`);}
 function goalDetails(g){const months=g.deadline&&g.deadline>=M.localDate(new Date())?Math.max(1,Math.ceil((new Date(g.deadline+'T23:59:59+07:00')-new Date())/(30.4375*86400000))):null;showDialog(esc(g.name),`${goalCard(g,true)}<p>Tiến độ do bạn ghi nhận; số dư tài khoản không thay đổi.</p>${months?`<p class="small-note">Phép tính kế hoạch: khoảng ${money(Math.ceil(Math.max(0,g.target-g.progress)/months))}/tháng trong ${months} tháng. Đây không phải khoản trích tiền tự động.</p>`:''}<div class="goal-buttons"><button class="secondary" data-edit-goal="${esc(g.id)}">Chỉnh sửa mục tiêu</button><button class="secondary" data-set-progress="${esc(g.id)}">Chỉnh sửa tiến độ</button><button class="secondary" data-clear-progress="${esc(g.id)}">Xóa tiến độ</button><button class="danger" data-delete-goal="${esc(g.id)}">Xóa mục tiêu</button></div><h3>Lịch sử cập nhật thủ công</h3>${g.history.length?g.history.map(h=>`<article class="progress-entry"><p>${esc(h.note)}</p><strong>${money(h.delta)}</strong><p>Tổng ghi nhận: ${money(h.total)}</p><small>${fullDate(h.date)}</small></article>`).join(''):'<p>Chưa ghi nhận tiến độ.</p>'}`);}
 function progressForm(id,mode='add'){const g=state.goals.find(g=>g.id===id);showDialog(mode==='add'?'Ghi nhận tiến độ':'Chỉnh sửa tiến độ',`<p>${esc(g.name)}</p><p class="unverified">Tiến độ do bạn ghi nhận; số dư tài khoản không thay đổi.</p><form id="progress-form" data-id="${esc(id)}" data-mode="${mode}" novalidate><label for="progress-value">${mode==='add'?'Số tiền ghi nhận thêm':'Tổng tiền đã ghi nhận mới'} (VND)</label><input id="progress-value" name="amount" type="${amountInputType()}" inputmode="numeric" value="${mode==='set'?g.progress:''}" required><p class="error" role="alert"></p><button class="primary">Lưu tiến độ</button></form>`);}
 function personal(){shell(`<div class="page-heading"><h1 tabindex="-1">Cá nhân</h1><p>Quản lý trải nghiệm NhTBank trên thiết bị này.</p></div><div class="personal-grid"><section class="panel"><h2>Hồ sơ minh họa</h2><p class="profile-display">${esc(name())}</p><details class="secondary-details"><summary>Chỉnh sửa hồ sơ</summary><form id="profile-form" novalidate><label for="profile-name">Tên hiển thị</label><input id="profile-name" name="name" maxlength="60" required value="${esc(name())}"><p class="error" role="alert"></p><button class="primary">Lưu hồ sơ</button></form></details><button class="text-link" data-action="account-info">Xem tài khoản mẫu</button></section><section class="panel"><h2>Tùy chọn hiển thị</h2>${[['hideBalance','Ẩn số dư','Chỉ che số dư tài khoản.'],['hideAll','Ẩn số tiền toàn ứng dụng','Che giao dịch, thống kê, mục tiêu và thông báo số tiền.'],['inAppNotifications','Thông báo trong ứng dụng','Chỉ lưu trong NhTBank; không gửi email hoặc thông báo thiết bị.']].map(([k,l,d])=>`<label class="setting-row"><span><strong>${l}</strong><small>${d}</small></span><input type="checkbox" role="switch" data-setting="${k}" ${state.settings[k]?'checked':''}></label>`).join('')}</section><section class="panel"><h2>Dịch vụ và bảo mật</h2><p>Chưa có dịch vụ ngân hàng, tra cứu người nhận, phát hành thẻ hay xác thực thật được kết nối.</p><button class="secondary" data-action="cards">Xem thẻ minh họa</button><button class="text-link" data-action="notifications">Trung tâm thông báo</button></section><section class="panel"><h2>Trợ giúp và dữ liệu</h2><button class="secondary" data-action="help">Trung tâm trợ giúp</button><button class="text-link" data-action="privacy">Chính sách dữ liệu minh họa</button><button class="secondary" data-action="reset">Đặt lại bản minh họa</button><button class="text-link" data-action="logout">Thoát bản minh họa</button></section></div>`);}
 function notifications(){const groups=[['transaction','Giao dịch'],['security','Bảo mật'],['service','Dịch vụ'],['goal','Mục tiêu']];showDialog('Trung tâm thông báo',`${groups.map(([type,label])=>`<h3>${label}</h3>${state.notifications.filter(n=>n.type===type).map(n=>`<button class="notification-row" data-notification="${esc(n.id)}"><strong>${esc(n.title)}</strong><span>${esc(n.body)}</span><small>${fullDate(n.date)} · ${n.read?'Đã đọc':'Chưa đọc'}</small></button>`).join('')||'<p class="small-note">Chưa có thông báo.</p>'}`).join('')}<button class="secondary" data-action="read-all">Đánh dấu tất cả đã đọc</button>`);}
 function qr(){shell(`<div class="page-heading"><h1 tabindex="-1">QR minh họa</h1><p>Mã chỉ chứa dữ liệu nhận diện mô phỏng; không phải mã VietQR thanh toán thật.</p></div><div class="filter-tabs qr-tabs"><button data-qr-tab="receive" aria-pressed="${qrTab==='receive'}" class="${qrTab==='receive'?'active':''}">Nhận tiền</button><button data-qr-tab="read" aria-pressed="${qrTab==='read'}" class="${qrTab==='read'?'active':''}">Đọc mã</button></div>${qrTab==='receive'?`<section class="panel qr-panel"><h2>Thông tin nhận minh họa</h2><p>${esc(name())} · Tài khoản mô phỏng<br>${maskedNumber}</p><button class="text-link" data-action="account-info">Xem thông tin đầy đủ</button><div id="qr-result"></div><details class="qr-customization"><summary>Thêm số tiền và nội dung</summary><form id="qr-form" novalidate><label for="qr-amount">Số tiền yêu cầu (VND, tùy chọn)</label><input id="qr-amount" name="amount" type="${amountInputType()}" inputmode="numeric" value="${esc(qrDraft.amount)}"><label for="qr-note">Nội dung</label><input id="qr-note" name="note" maxlength="100" value="${esc(qrDraft.note)}"><p class="error" role="alert"></p><button class="primary">Tạo QR minh họa</button></form></details></section>`:`<section class="panel qr-panel"><h2>Đọc QR minh họa NhTBank</h2><p>Mã lạ chỉ được thông báo; không mở liên kết hoặc chuyển tiền tự động.</p><button class="primary" data-action="start-camera">Mở camera đọc mã</button><button class="secondary" data-action="stop-camera">Dừng camera</button><video id="scan-video" playsinline muted hidden></video><label for="qr-image">Hoặc chọn ảnh QR trên thiết bị</label><input id="qr-image" type="file" accept="image/*"><p id="scan-status" role="status"></p><canvas id="scan-canvas" hidden></canvas></section>`}`);if(qrTab==='receive'&&!state.settings.hideAll)generateQR();}
 function generateQR(){const payload=M.qrPayload(M.parseMoney(qrDraft.amount,true),qrDraft.note,name());lastQR=payload;const qr=window.qrcode(0,'M');qr.addData(payload);qr.make();const count=qr.getModuleCount(),scale=Math.max(3,Math.ceil(360/(count+8))),size=(count+8)*scale;const canvas=document.createElement('canvas');canvas.width=size;canvas.height=size+96;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#172B24';for(let r=0;r<count;r++)for(let c=0;c<count;c++)if(qr.isDark(r,c))ctx.fillRect((c+4)*scale,(r+4)*scale,scale,scale);ctx.fillStyle='#075E50';ctx.font='bold 16px sans-serif';ctx.textAlign='center';ctx.fillText('NhTBank · QR MINH HỌA',size/2,size+28);ctx.font='13px sans-serif';ctx.fillText('Không phải mã thanh toán',size/2,size+53);ctx.fillText('Không chuyển tiền thật',size/2,size+76);canvas.setAttribute('aria-label','QR minh họa NhTBank, không phải mã thanh toán');canvas.setAttribute('role','img');qrURL=canvas.toDataURL('image/png');document.getElementById('qr-result').replaceChildren(canvas);document.getElementById('qr-result').insertAdjacentHTML('beforeend',`<p class="small-note">Ảnh tải xuống giữ nhãn minh họa.</p><div class="goal-buttons"><button class="secondary" data-action="download-qr">Tải ảnh QR (.png)</button><button class="secondary" data-action="copy-qr-info">Sao chép thông tin</button><button class="secondary" data-action="share-qr">Chia sẻ ảnh</button></div>`);}
 function scanned(raw){try{const p=M.readQR(raw);stopCamera();showDialog('Kiểm tra dữ liệu QR minh họa',`<p class="receipt-watermark">MÔ PHỎNG — Không phải mã thanh toán</p><dl>${[['Chủ tài khoản',p.holder],['Đơn vị',p.provider],['Số tài khoản',p.account],['Số tiền',p.amount===null?'Người chuyển tự nhập':money(p.amount)],['Nội dung',p.note]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><button class="primary" data-action="use-scanned">Dùng thông tin cho chuyển mô phỏng</button>`);dialog.dataset.scanned=JSON.stringify(p);}catch(e){const el=document.getElementById('scan-status');if(el)el.textContent=e.message;}}
 async function readImage(file){stopCamera();if(!file)return;if(!file.type.startsWith('image/')||file.size>15*1024*1024){document.getElementById('scan-status').textContent='Chọn ảnh dưới 15 MB.';return;}const url=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});if(route!=='qr'||qrTab!=='read')return;const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.getElementById('scan-canvas');canvas.width=image.width*scale;canvas.height=image.height*scale;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height),code=window.jsQR(data.data,data.width,data.height);if(code)scanned(code.data);else document.getElementById('scan-status').textContent='Chưa đọc được QR trong ảnh. Chọn ảnh rõ mã và đủ viền trắng.';}catch{if(document.getElementById('scan-status'))document.getElementById('scan-status').textContent='Không thể đọc ảnh này. Hãy chọn PNG hoặc JPEG.';}finally{URL.revokeObjectURL(url);}}
 async function startCamera(){if(cameraBusy||stream)return;const status=document.getElementById('scan-status');if(!navigator.mediaDevices?.getUserMedia){status.textContent='Camera không khả dụng tại địa chỉ này. Dùng HTTPS hoặc localhost, hoặc chọn ảnh QR.';return;}cameraBusy=true;const ticket=++cameraRequest;status.textContent='Đang xin quyền camera…';try{const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});if(ticket!==cameraRequest||route!=='qr'||qrTab!=='read'||document.hidden){media.getTracks().forEach(t=>t.stop());return;}stream=media;const video=document.getElementById('scan-video');video.srcObject=stream;video.hidden=false;await video.play();status.textContent='Đưa mã vào khung hình. Camera không gửi ảnh lên mạng.';const scan=()=>{if(!stream||route!=='qr'||qrTab!=='read')return;const canvas=document.getElementById('scan-canvas');if(video.readyState>=2){const scale=Math.min(1,800/video.videoWidth);canvas.width=video.videoWidth*scale;canvas.height=video.videoHeight*scale;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(video,0,0,canvas.width,canvas.height);const d=ctx.getImageData(0,0,canvas.width,canvas.height),code=jsQR(d.data,d.width,d.height);if(code){scanned(code.data);if(!stream)return;}}scanTimer=setTimeout(scan,300);};scan();}catch(e){if(status.isConnected)status.textContent=e.name==='NotAllowedError'?'Quyền camera bị từ chối. Bật quyền camera cho trình duyệt hoặc chọn ảnh QR bên dưới.':'Chưa mở được camera. Hãy thử lại hoặc chọn ảnh QR.';stopCamera();}finally{if(ticket===cameraRequest)cameraBusy=false;}}
 function qrBlob(){return new Blob([Uint8Array.from(atob(qrURL.split(',')[1]),c=>c.charCodeAt(0))],{type:'image/png'});}
 function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Đã sao chép thông tin minh họa.');}catch{showDialog('Sao chép thủ công',`<p>Trình duyệt không cho sao chép tự động. Chọn nội dung dưới đây.</p><textarea readonly aria-label="Nội dung để sao chép">${esc(text)}</textarea>`);}}
 function exportPreview(task){exportTask=task;showDialog('Kiểm tra phạm vi tệp xuất',`<p>Tệp ${task.type==='history'?'CSV lịch sử':'TXT biên nhận'} sẽ chứa số tiền đầy đủ, số tài khoản, mã giao dịch, thời gian UTC+7 và dấu MÔ PHỎNG.</p><p>${state.settings.hideAll?'Bạn đang ẩn số tiền toàn ứng dụng. Xuất tệp sẽ đưa số tiền đầy đủ vào tệp.':'Hãy bảo quản tệp vì có thông tin tài khoản mô phỏng và giao dịch.'}</p><p>${task.type==='history'?task.list.length+' giao dịch · Bộ lọc: '+esc(JSON.stringify(task.filters)):'Một biên nhận mô phỏng'}</p><div class="dialog-actions"><button class="secondary" data-action="close">Hủy xuất</button><button class="primary" data-action="export-confirm">Xuất tệp với số tiền đầy đủ</button></div>`);}
 function exportFile(){if(!exportTask)return;const task=exportTask;exportTask=null;if(task.type==='receipt'){const t=task.transaction;const text=['MÔ PHỎNG — Không phải chứng từ thanh toán','NhTBank · Bản minh họa',`Trạng thái: Hoàn tất (mô phỏng)`,`Mã: ${t.id}`,`Thời gian: ${fullDate(t.date)}`,`Nguồn: ${t.amount<0?M.owner.number+' · Tài khoản mô phỏng':t.account+' · '+t.bank}`,`Người giao dịch: ${t.name}`,`Ngân hàng mẫu: ${t.bank}`,`Tài khoản đối ứng: ${t.account}`,`Số tiền: ${cash(Math.abs(t.amount))}`,`Phí mô phỏng: ${cash(t.fee||0)}`,`Tổng tiền trừ: ${t.amount<0?cash(-t.amount+(t.fee||0)):'Không áp dụng'}`,`Nội dung: ${t.note}`].join('\n');download(new Blob([text],{type:'text/plain;charset=utf-8'}),'NhTBank-bien-nhan-MO-PHONG.txt');}else{const csvCell=v=>{let text=String(v);if(typeof v!=='number'&&/^[\s=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};const rows=[['MÔ PHỎNG — Không phải chứng từ thanh toán'],['Tài khoản',M.owner.number],['Xuất lúc',fullDate(new Date())],['Bộ lọc',JSON.stringify(task.filters)],['Mã','Thời gian UTC+7','Người giao dịch','Ngân hàng mẫu','Tài khoản đối ứng','Số tiền VND','Phí VND','Trạng thái','Nội dung','Danh mục','Chế độ'],...task.list.map(t=>[t.id,fullDate(t.date),t.name,t.bank,t.account,t.amount,t.fee||0,'Hoàn tất',t.note,M.categories[t.category],'MÔ PHỎNG'])];download(new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'NhTBank-lich-su-MO-PHONG.csv');}closeDialog();toast('Đã tạo tệp có nhãn MÔ PHỎNG.');}
 function infoAccount(){showDialog('Tài khoản minh họa',`<dl>${[['Chủ tài khoản',name()],['Đơn vị cung cấp','Tài khoản mô phỏng · Dữ liệu cục bộ'],['Số tài khoản',M.owner.number],['Số dư khả dụng',state.settings.hideBalance?'••••••':money(state.balance)],['Cập nhật',fullDate(state.accountUpdatedAt)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><button class="primary" data-action="copy">Sao chép số tài khoản</button><p class="small-note">Không chuyển tiền thật vào số tài khoản mẫu này.</p>`);}
 function privacy(){showDialog('Dữ liệu và quyền riêng tư',`<p>Bản minh họa chỉ lưu trên trình duyệt, không gửi giao dịch, QR, ảnh hay camera lên máy chủ.</p><p>Xóa dữ liệu trình duyệt có thể làm mất tiến độ và lịch sử. Thiết bị hoặc địa chỉ website khác có vùng dữ liệu riêng. Nếu không cho lưu, ứng dụng chỉ giữ trong phiên đang mở.</p><p>Không nhập mật khẩu ngân hàng, OTP, số thẻ thật hoặc API Key vào bản minh họa.</p><p>Phiên bản này chưa cung cấp tài khoản, chuyển tiền, phát hành thẻ hoặc quản lý phiên bảo mật thật.</p>`);}
 function help(){showDialog('Trung tâm trợ giúp',`<details open><summary>Chưa thấy tiền đến</summary><p>Bản minh họa không nhận tiền thật. Dữ liệu tiền vào hiện tại là mẫu đã có sẵn.</p></details><details><summary>Giao dịch đang xử lý hoặc chưa xác định</summary><p>Bản này xử lý mô phỏng cục bộ. Với dịch vụ thật, cần kiểm tra trạng thái tại đơn vị xử lý trước khi gửi lại. Chưa có dịch vụ thật được kết nối trong NhTBank.</p></details><details><summary>Chuyển nhầm thông tin</summary><p>Hãy kiểm tra ở bước xác nhận. Bản minh họa không gửi tiền thật; có thể đặt lại dữ liệu. Không có chức năng hủy hay thu hồi giao dịch ngân hàng.</p></details><details><summary>Không truy cập được tài khoản</summary><p>Không cần đăng nhập ngân hàng. Nếu dữ liệu cục bộ không đọc được, ứng dụng sẽ báo và dùng phiên mẫu mới.</p></details><details><summary>Bảo vệ tài khoản</summary><p>Không chia sẻ OTP, mật khẩu hoặc thông tin thẻ. Chưa có kênh hỗ trợ khách hàng đã xác nhận; ứng dụng không cung cấp số điện thoại giả.</p></details><button class="secondary" data-action="privacy">Cách lưu dữ liệu</button>`);}
 function cards(){showDialog('Thẻ minh họa',`<p>Chưa có thẻ thật hoặc đơn vị phát hành được kết nối.</p><section class="sample-card"><strong>THẺ MẪU · NHTBANK</strong><p>•••• •••• •••• 1234</p><small>${esc(name())}</small><p>${state.cardLocked?'🔒 Đã khóa mô phỏng':'✓ Đang mở mô phỏng'}</p></section><p>Trạng thái chỉ thay đổi trong bản minh họa. Không có hạn mức hay khả năng thanh toán thật.</p><button class="primary" data-action="card-toggle">${state.cardLocked?'Mở khóa':'Khóa'} thẻ mô phỏng</button>`);}
 function analysis(){const stats=M.monthStats(state),tx=state.transactions.filter(t=>t.status==='completed'&&t.amount<0&&M.localDate(t.date).startsWith(stats.month));const totals=Object.fromEntries(Object.keys(M.categories).map(c=>[c,tx.filter(t=>t.category===c).reduce((n,t)=>n-t.amount,0)]));showDialog('Dòng tiền và chi tiêu',`<p>Tài khoản ${maskedNumber} · Kỳ ${stats.month} · Chỉ giao dịch hoàn tất.</p><dl>${[['Tiền vào',stats.income],['Tiền ra',stats.outgoing],['Chênh lệch',stats.net],['Chi tiêu đã phân loại',stats.spending]].map(([k,v])=>`<div><dt>${k}</dt><dd>${money(v)}</dd></div>`).join('')}</dl><p class="small-note">Chuyển tiền và chuyển giữa tài khoản của tôi không được xem là chi tiêu. Tiến độ mục tiêu thủ công không phải dòng tiền ngân hàng. Bản minh họa chưa có giao dịch đang xử lý, thất bại hoặc hoàn tiền.</p><h3>Tiền ra theo danh mục</h3><div class="chart" aria-label="Tiền ra theo danh mục, có số liệu bằng chữ">${Object.entries(totals).filter(([,n])=>n>0).map(([c,n])=>`<div><span>${M.categories[c]}</span><strong>${money(n)}</strong><div class="goal-track"><span style="width:${state.settings.hideAll?0:Math.min(100,n/Math.max(1,stats.outgoing)*100)}%"></span></div></div>`).join('')||'<p>Chưa có tiền ra trong kỳ này.</p>'}</div>`);}
 async function action(a){
  if(a==='close')closeDialog();
  else if(a==='leave-form'){closeDialog();draft=null;performNavigate(pendingRoute);}
  else if(a==='filters')filterDialog();
  else if(a==='balance'){state.settings.hideBalance=!state.settings.hideBalance;save();home();document.querySelector('[data-action="balance"]')?.focus();}
  else if(a==='copy')copyText(M.owner.number);
  else if(a==='account-info')infoAccount();
  else if(a==='privacy')privacy();
  else if(a==='help')help();
  else if(a==='cards')cards();
  else if(a==='analysis')analysis();
  else if(a==='notifications')notifications();
  else if(a==='read-all'){state.notifications=state.notifications.map(n=>({...n,read:true}));save();notifications();}
  else if(a==='edit'){closeDialog();transferStep=1;transfer();document.getElementById('account').focus();}
  else if(a==='confirm'&&draft){
   const b=dialog.querySelector('[data-action="confirm"]');b.disabled=true;b.textContent='Đang xử lý…';dialog.setAttribute('aria-busy','true');
   try{const result=M.transfer(state,draft);state=result.state;draft=null;save();dialog.removeAttribute('aria-busy');receipt(result.transaction,true);}catch(e){dialog.removeAttribute('aria-busy');document.getElementById('confirm-error').textContent=e.message;b.disabled=false;b.textContent='Xác nhận chuyển tiền mô phỏng';}
  }
  else if(a==='new-goal')goalForm();
  else if(a==='clear-filters'){filters={query:'',direction:'all',status:'',from:'',to:''};history();}
  else if(a==='export-history')exportPreview({type:'history',list:filtered(),filters:{...filters}});
  else if(a==='export-confirm')exportFile();
  else if(a==='reset')showDialog('Đặt lại bản minh họa?',`<p>Sẽ thay thế dữ liệu của phiên bản này: số dư và lịch sử mô phỏng, mục tiêu và lịch sử ghi nhận, hồ sơ, thông báo, tùy chọn hiển thị và trạng thái thẻ mẫu.</p><p>Dữ liệu phiên bản cũ được giữ ở vùng lưu riêng.</p><div class="dialog-actions"><button class="secondary" data-action="close">Giữ lại</button><button class="primary" data-action="reset-confirm">Xác nhận đặt lại</button></div>`);
  else if(a==='reset-confirm'){state=M.initial();save();draft=null;filters={query:'',direction:'all',status:'',from:'',to:''};qrDraft={amount:'',note:''};closeDialog();performNavigate('home');toast('Đã đặt lại dữ liệu minh họa.');}
  else if(a==='logout')showDialog('Rời bản minh họa?',`<p>Dữ liệu đã lưu vẫn được giữ trên thiết bị. Đây không phải phiên đăng nhập ngân hàng thật.</p><div class="dialog-actions"><button class="secondary" data-action="close">Ở lại</button><button class="primary" data-action="logout-confirm">Đăng xuất</button></div>`);
  else if(a==='logout-confirm'){closeDialog();performNavigate('welcome');}
  else if(a==='card-toggle')showDialog('Xác nhận đổi trạng thái thẻ mẫu',`<p>Thẻ sẽ được ${state.cardLocked?'mở khóa':'khóa'} trong bản minh họa. Không tác động tới thẻ thật.</p><button class="primary" data-action="card-confirm">Xác nhận ${state.cardLocked?'mở khóa':'khóa'} mô phỏng</button>`);
  else if(a==='card-confirm'){state.cardLocked=!state.cardLocked;if(state.settings.inAppNotifications)state.notifications.unshift({id:'CARD-'+Date.now(),title:'Đã đổi trạng thái thẻ mẫu',body:'Thao tác bảo mật chỉ có hiệu lực trong bản minh họa.',type:'security',target:'cards',date:new Date().toISOString(),read:false});state.notifications=state.notifications.slice(0,200);save();cards();}
  else if(a==='start-camera')startCamera();
  else if(a==='stop-camera'){stopCamera();document.getElementById('scan-video').hidden=true;document.getElementById('scan-status').textContent='Đã dừng camera.';}
  else if(a==='download-qr'&&qrURL){download(qrBlob(),'NhTBank-QR-MINH-HOA.png');}
  else if(a==='copy-qr-info'&&lastQR){const p=M.readQR(lastQR);copyText(`${MODE}\n${p.holder}\n${p.provider}\nSố tài khoản mẫu: ${p.account}\nSố tiền: ${p.amount===null?'Tự nhập':money(p.amount)}\nNội dung: ${p.note}`);}
  else if(a==='share-qr'&&qrURL){const blob=qrBlob(),file=new File([blob],'NhTBank-QR-MINH-HOA.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'QR minh họa NhTBank',text:MODE});}catch(e){if(e.name!=='AbortError')toast('Không chia sẻ được. Bạn có thể tải ảnh QR.');}}else toast('Thiết bị chưa hỗ trợ chia sẻ ảnh. Hãy dùng nút Tải ảnh QR.');}
  else if(a==='use-scanned'){const p=JSON.parse(dialog.dataset.scanned);draft={bank:M.owner.bank,account:p.account,name:p.holder,amount:p.amount||'',note:p.note};closeDialog();performNavigate('transfer');}
 }
 function findGoal(id){return state.goals.find(g=>g.id===id);}
 function handleClick(event){const b=event.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.route)navigate(b.dataset.route);
  else if(b.dataset.action)Promise.resolve(action(b.dataset.action)).catch(()=>toast('Chưa thực hiện được thao tác. Hãy thử lại.'));
  else if(b.dataset.amount)document.getElementById('amount').value=String(b.dataset.amount);
  else if(b.dataset.transaction)receipt(state.transactions.find(t=>t.id===b.dataset.transaction));
  else if(b.dataset.exportReceipt)exportPreview({type:'receipt',transaction:state.transactions.find(t=>t.id===b.dataset.exportReceipt)});
  else if(b.dataset.progress)progressForm(b.dataset.progress);
  else if(b.dataset.setProgress)progressForm(b.dataset.setProgress,'set');
  else if(b.dataset.goal)goalDetails(findGoal(b.dataset.goal));
  else if(b.dataset.editGoal)goalForm(findGoal(b.dataset.editGoal));
  else if(b.dataset.deleteGoal)showDialog('Xóa mục tiêu và lịch sử?',`<p>Chỉ xóa kế hoạch thủ công, không thay đổi số dư tài khoản.</p><div class="dialog-actions"><button class="secondary" data-action="close">Giữ lại</button><button class="primary" data-remove-goal="${esc(b.dataset.deleteGoal)}">Xác nhận xóa mục tiêu</button></div>`);
  else if(b.dataset.clearProgress)showDialog('Xóa tiến độ đã ghi nhận?',`<p>Tiến độ trở về 0, lịch sử giữ lại lần điều chỉnh để đối chiếu. Số dư tài khoản không đổi.</p><button class="primary" data-confirm-clear-progress="${esc(b.dataset.clearProgress)}">Xác nhận xóa tiến độ</button>`);
  else if(b.dataset.confirmClearProgress){state=M.progressGoal(state,b.dataset.confirmClearProgress,'0','set');save();closeDialog();render();toast('Đã xóa tiến độ hiện tại, giữ lịch sử điều chỉnh.');}
  else if(b.dataset.removeGoal){state.goals=state.goals.filter(g=>g.id!==b.dataset.removeGoal);save();closeDialog();render();toast('Đã xóa mục tiêu thủ công.');}
  else if(b.dataset.direction){filters.direction=b.dataset.direction;history();}
  else if(b.dataset.clearFilter){filters[b.dataset.clearFilter]=b.dataset.clearFilter==='direction'?'all':'';history();}
  else if(b.dataset.qrTab){if(dirty()){showDialog('Biểu mẫu QR chưa lưu',`<p>Hãy tạo QR để giữ nội dung trước khi đổi phần.</p>`);return;}stopCamera();qrTab=b.dataset.qrTab;qr();}
  else if(b.dataset.notification){const n=state.notifications.find(n=>n.id===b.dataset.notification);n.read=true;save();if(n.type==='transaction'){const t=state.transactions.find(t=>t.id===n.target);if(t)receipt(t);else notifications();}else if(n.type==='goal'&&findGoal(n.target))goalDetails(findGoal(n.target));else if(n.type==='security')cards();else showDialog(esc(n.title),`<p>${esc(n.body)}</p><small>${fullDate(n.date)}</small>`);}
 }
 function submit(event){const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error,.error').forEach(el=>el.textContent='');const data=Object.fromEntries(new FormData(form));
  try{
   if(form.id==='transfer-form'){draft=M.transferDraft(state,transferErrors(form));form.dataset.baseline=JSON.stringify([...new FormData(form)]);review();}
   else if(form.id==='history-search'){filters.query=data.query;form.dataset.baseline=JSON.stringify([...new FormData(form)]);updateHistory();}
   else if(form.id==='history-filter'){if(data.from&&data.to&&data.from>data.to){document.getElementById('from').focus();throw Error('Ngày bắt đầu phải trước hoặc bằng ngày kết thúc.');}filters={...filters,...data};closeDialog(true);history();}
   else if(form.id==='goal-form'){state=M.saveGoal(state,data,form.dataset.id);save();closeDialog(true);render();toast('Đã lưu mục tiêu thủ công.');}
   else if(form.id==='progress-form'){state=M.progressGoal(state,form.dataset.id,data.amount,form.dataset.mode);save();closeDialog(true);render();toast('Đã ghi nhận tiến độ. Số dư tài khoản giữ nguyên.');}
   else if(form.id==='profile-form'){const value=data.name.trim();if(!value||value.length>60)throw Error('Tên hiển thị cần có từ 1 đến 60 ký tự.');state.profile.name=value;save();personal();toast('Đã lưu hồ sơ minh họa.');}
   else if(form.id==='qr-form'){if(state.settings.hideAll)throw Error('Đang ẩn số tiền toàn ứng dụng. Tắt tùy chọn này trước khi hiển thị mã QR chứa số tiền.');qrDraft={amount:data.amount,note:data.note};generateQR();form.dataset.baseline=JSON.stringify([...new FormData(form)]);}
  }catch(e){const el=form.querySelector('.error');if(el)el.textContent=e.message;const invalid=form.querySelector('[aria-invalid="true"]');if(!invalid)form.querySelector('input')?.focus();}
 }
 function changed(event){const el=event.target;
  if(el.id==='recipient'&&el.value==='anh'){document.getElementById('bank').value=M.owner.bank;document.getElementById('account').value='0987654321';document.getElementById('name').value='Nguyễn Minh Anh';}
  if(el.dataset.setting){state.settings[el.dataset.setting]=el.checked;save();personal();app.querySelector(`[data-setting="${el.dataset.setting}"]`)?.focus();}
  if(el.dataset.categoryTransaction){const t=state.transactions.find(t=>t.id===el.dataset.categoryTransaction);if(t&&Object.hasOwn(M.categories,el.value)){t.category=el.value;save();toast('Đã đổi danh mục. Số dư không thay đổi.');}}
  if(el.id==='qr-image')readImage(el.files?.[0]);
 }
 app.addEventListener('input',e=>{if(e.target.id==='search'){filters.query=e.target.value;e.target.form.dataset.baseline=JSON.stringify([...new FormData(e.target.form)]);updateHistory();}});
 app.onclick=handleClick;app.onsubmit=submit;app.onchange=changed;
 dialog.onclick=event=>{if(event.target===dialog){closeDialog();return;}handleClick(event);};dialog.onsubmit=submit;dialog.onchange=changed;
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera();});window.addEventListener('pagehide',stopCamera);
 for(const event of ['online','offline'])window.addEventListener(event,()=>{if(dirty())toast(navigator.onLine?'Đã có kết nối mạng.':'Bạn đang ngoại tuyến. Biểu mẫu đang nhập được giữ.');else render();});
 function render(){if(route==='qr')stopCamera();({welcome,home,transfer,history,qr,goals,personal}[route]||home)();}
 render();
})();
